/**
 * Shared report period filter — LinReportPeriodSelector + computed date range.
 * Default viewMode = year (01/01 → 31/12) per SCYK /filter-dates-context.
 */
import { useCallback, useMemo, useState } from 'react';
import {
  computeReportPeriodDates,
  nowMonth,
  nowQuarter,
  nowYear,
  yearOptionsFromStartYear,
  type ViewMode,
  type LinReportPeriodSelectorLabels,
} from '@linm-soft-org/linm-web-common-components';

export const REPORT_PERIOD_LABELS: LinReportPeriodSelectorLabels = {
  viewMode: 'Xem theo',
  fieldMonth: 'Tháng',
  fieldYear: 'Năm',
  fieldQuarter: 'Quý',
};

export function currentYearDateRange(): { dateFrom: string; dateTo: string } {
  const y = nowYear();
  const { fromDate, toDate } = computeReportPeriodDates('year', nowMonth(), y, nowQuarter());
  return { dateFrom: fromDate, dateTo: toDate };
}

export function reportYearOptions() {
  const startYear = Number(import.meta.env.VITE_START_YEAR);
  return yearOptionsFromStartYear(Number.isFinite(startYear) ? startYear : new Date().getFullYear() - 5);
}

export interface ReportPeriodFilterState {
  viewMode: ViewMode;
  month: string;
  year: string;
  quarter: string;
  fromDate: string;
  toDate: string;
  setMonth: (v: string) => void;
  setYear: (v: string) => void;
  setQuarter: (v: string) => void;
  handleViewModeChange: (mode: ViewMode) => void;
  handleDateRangeChange: (from?: string, to?: string) => void;
  /** Reset to default year (current) */
  resetToDefaultYear: () => void;
  yearOptions: ReturnType<typeof reportYearOptions>;
  periodLabels: LinReportPeriodSelectorLabels;
}

/**
 * @param onDatesCommit — called when computed/manual dates change (update draft + optional search)
 */
export function useReportPeriodFilter(
  onDatesCommit?: (dateFrom: string, dateTo: string) => void,
  defaultViewMode: ViewMode = 'year',
): ReportPeriodFilterState {
  const yearOptions = useMemo(() => reportYearOptions(), []);
  const initial = useMemo(() => {
    const y = nowYear();
    const m = nowMonth();
    const q = nowQuarter();
    const computed = computeReportPeriodDates(defaultViewMode, m, y, q);
    return { y, m, q, computed };
  }, [defaultViewMode]);

  const [viewMode, setViewMode] = useState<ViewMode>(defaultViewMode);
  const [month, setMonth] = useState(initial.m);
  const [year, setYear] = useState(initial.y);
  const [quarter, setQuarter] = useState(initial.q);
  const [manualFromDate, setManualFromDate] = useState('');
  const [manualToDate, setManualToDate] = useState('');

  const computed = useMemo(
    () => computeReportPeriodDates(viewMode, month, year, quarter),
    [viewMode, month, year, quarter],
  );

  const fromDate = viewMode === 'day' ? manualFromDate : computed.fromDate;
  const toDate = viewMode === 'day' ? manualToDate : computed.toDate;

  const commit = useCallback(
    (from: string, to: string) => {
      onDatesCommit?.(from, to);
    },
    [onDatesCommit],
  );

  const handleViewModeChange = useCallback(
    (mode: ViewMode) => {
      if (mode === viewMode) return;
      let nextFrom = '';
      let nextTo = '';
      let nextMonth = month;
      let nextYear = year;
      let nextQuarter = quarter;

      if (mode === 'day') {
        const cur = computeReportPeriodDates(viewMode, month, year, quarter);
        nextFrom = cur.fromDate || `${year}-01-01`;
        nextTo = cur.toDate || `${year}-12-31`;
        setManualFromDate(nextFrom);
        setManualToDate(nextTo);
      } else {
        setManualFromDate('');
        setManualToDate('');
        if (mode === 'month') {
          nextMonth = nowMonth();
          nextYear = nowYear();
          setMonth(nextMonth);
          setYear(nextYear);
        }
        if (mode === 'quarter') {
          nextQuarter = nowQuarter();
          nextYear = nowYear();
          setQuarter(nextQuarter);
          setYear(nextYear);
        }
        if (mode === 'year') {
          nextYear = nowYear();
          setYear(nextYear);
        }
        const cur = computeReportPeriodDates(mode, nextMonth, nextYear, nextQuarter);
        nextFrom = cur.fromDate;
        nextTo = cur.toDate;
      }
      setViewMode(mode);
      commit(nextFrom, nextTo);
    },
    [viewMode, month, year, quarter, commit],
  );

  const handleDateRangeChange = useCallback(
    (from?: string, to?: string) => {
      const nextFrom = from ?? '';
      const nextTo = to ?? '';
      setManualFromDate(nextFrom);
      setManualToDate(nextTo);
      if (viewMode !== 'day') setViewMode('day');
      commit(nextFrom, nextTo);
    },
    [viewMode, commit],
  );

  const setMonthAndCommit = useCallback(
    (v: string) => {
      setMonth(v);
      if (viewMode === 'day') return;
      const cur = computeReportPeriodDates(viewMode, v, year, quarter);
      commit(cur.fromDate, cur.toDate);
    },
    [viewMode, year, quarter, commit],
  );

  const setYearAndCommit = useCallback(
    (v: string) => {
      setYear(v);
      if (viewMode === 'day') return;
      const cur = computeReportPeriodDates(viewMode, month, v, quarter);
      commit(cur.fromDate, cur.toDate);
    },
    [viewMode, month, quarter, commit],
  );

  const setQuarterAndCommit = useCallback(
    (v: string) => {
      setQuarter(v);
      if (viewMode === 'day') return;
      const cur = computeReportPeriodDates(viewMode, month, year, v);
      commit(cur.fromDate, cur.toDate);
    },
    [viewMode, month, year, commit],
  );

  const resetToDefaultYear = useCallback(() => {
    const y = nowYear();
    const m = nowMonth();
    const q = nowQuarter();
    setViewMode('year');
    setMonth(m);
    setYear(y);
    setQuarter(q);
    setManualFromDate('');
    setManualToDate('');
    const cur = computeReportPeriodDates('year', m, y, q);
    commit(cur.fromDate, cur.toDate);
  }, [commit]);

  return {
    viewMode,
    month,
    year,
    quarter,
    fromDate,
    toDate,
    setMonth: setMonthAndCommit,
    setYear: setYearAndCommit,
    setQuarter: setQuarterAndCommit,
    handleViewModeChange,
    handleDateRangeChange,
    resetToDefaultYear,
    yearOptions,
    periodLabels: REPORT_PERIOD_LABELS,
  };
}
