import React, { useEffect } from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { navigateToUrl } from 'single-spa';
import { useAppSelector } from '../../store/hooks';
import { UserRole } from '../../models/User';
import {
  ForbiddenPage,
  hasValidAuthToken,
} from '@linm-soft-org/linm-web-common-components';
import { getHomePath, isPathAllowed } from '../../utils/navUtils';
import { isStandalone } from '../../dev/isStandalone';

interface ProtectedRouteProps {
  children: React.ReactNode;
  allowedRoles?: UserRole[];
}

/**
 * Protected route component that requires authentication.
 *
 * Guard order:
 *  1. Not authenticated → shell `/login` (embedded) or MemoryRouter `/login` (standalone)
 *  2. allowedRoles specified but user's role not included → redirect to /unauthorized
 *  3. Current path not covered by the user's menu → redirect to /unauthorized
 */
export const ProtectedRoute: React.FC<ProtectedRouteProps> = ({
  children,
  allowedRoles,
}) => {
  const { isAuthenticated, user } = useAppSelector((state) => state.auth);
  const location = useLocation();

  const needsLogin = !isAuthenticated || !hasValidAuthToken();

  useEffect(() => {
    if (!needsLogin || isStandalone) return;
    navigateToUrl('/login');
  }, [needsLogin]);

  if (needsLogin) {
    if (isStandalone) {
      return <Navigate to="/login" replace />;
    }
    return null;
  }

  if (location.pathname === '/') {
    const homePath = getHomePath(user?.role, user?.package, user?.defaultMenuUrl);
    return <Navigate to={homePath} replace />;
  }

  if (allowedRoles && allowedRoles.length > 0 && user) {
    if (!allowedRoles.includes(user.role)) {
      return <ForbiddenPage />;
    }
  }

  if (user && !isPathAllowed(user.role, user.package, location.pathname)) {
    return <ForbiddenPage />;
  }

  return <>{children}</>;
};
