import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import type { MedicalIncidentAttachment } from '../../models/MedicalIncident';
import type {
  IncidentDetection,
  IncidentDetectionFilters,
  IncidentDetectionStats,
} from '../../models/IncidentDetection';

export interface PagedResult<T> {
  items: T[];
  total: number;
  page: number;
  pageSize: number;
}

const toPayload = (data: Partial<IncidentDetection>) => ({
  description: data.description ?? '',
  detectedAt: data.detectedAt,
  locationText: data.locationText ?? null,
  targetDepartmentId: data.targetDepartmentId,
  targetDepartmentName: data.targetDepartmentName ?? '',
  attachments: data.attachments ?? [],
});

export const incidentDetectionEndpoint = {
  getList: async (
    filters: IncidentDetectionFilters,
    page: number,
    pageSize: number,
  ): Promise<PagedResult<IncidentDetection>> => {
    const params = new URLSearchParams({
      page: String(page),
      pageSize: String(pageSize),
      ...(filters.search && { search: filters.search }),
      ...(filters.status && { status: filters.status }),
      ...(filters.inbox && { inbox: filters.inbox }),
      ...(filters.targetDepartmentId && { targetDepartmentId: filters.targetDepartmentId }),
    });
    const res = await apiClient.get<BffResponse<{
      items: IncidentDetection[];
      totalCount: number;
      page: number;
      pageSize: number;
    }>>(`/incident-detections?${params}`);
    const data = unwrap(res);
    return {
      items: data.items,
      total: data.totalCount,
      page: data.page,
      pageSize: data.pageSize,
    };
  },

  getStats: async (): Promise<IncidentDetectionStats> => {
    const res = await apiClient.get<BffResponse<IncidentDetectionStats>>('/incident-detections/stats');
    return unwrap(res);
  },

  getById: async (id: string): Promise<IncidentDetection | null> => {
    const res = await apiClient.get<BffResponse<IncidentDetection>>(`/incident-detections/${id}`);
    return unwrap(res);
  },

  create: async (data: Partial<IncidentDetection>): Promise<IncidentDetection> => {
    const res = await apiClient.post<BffResponse<IncidentDetection>>(
      '/incident-detections',
      toPayload(data),
    );
    return unwrap(res);
  },

  update: async (id: string, data: Partial<IncidentDetection>): Promise<IncidentDetection> => {
    const res = await apiClient.put<BffResponse<IncidentDetection>>(
      `/incident-detections/${id}`,
      toPayload(data),
    );
    return unwrap(res);
  },

  route: async (id: string): Promise<IncidentDetection> => {
    const res = await apiClient.post<BffResponse<IncidentDetection>>(`/incident-detections/${id}/route`);
    return unwrap(res);
  },

  claim: async (id: string): Promise<IncidentDetection> => {
    const res = await apiClient.post<BffResponse<IncidentDetection>>(`/incident-detections/${id}/claim`);
    return unwrap(res);
  },

  reassign: async (
    id: string,
    targetDepartmentId: string,
    targetDepartmentName: string,
  ): Promise<IncidentDetection> => {
    const res = await apiClient.post<BffResponse<IncidentDetection>>(
      `/incident-detections/${id}/reassign`,
      { targetDepartmentId, targetDepartmentName },
    );
    return unwrap(res);
  },

  reject: async (id: string, reason: string): Promise<IncidentDetection> => {
    const res = await apiClient.post<BffResponse<IncidentDetection>>(
      `/incident-detections/${id}/reject`,
      { reason },
    );
    return unwrap(res);
  },

  cancel: async (id: string): Promise<IncidentDetection> => {
    const res = await apiClient.post<BffResponse<IncidentDetection>>(`/incident-detections/${id}/cancel`);
    return unwrap(res);
  },

  convert: async (id: string): Promise<{ id: string }> => {
    const res = await apiClient.post<BffResponse<{ id: string }>>(`/incident-detections/${id}/convert`);
    return unwrap(res);
  },
};

export type { MedicalIncidentAttachment };
