import type {
  IncidentDetection,
  IncidentDetectionFilters,
  IncidentDetectionStats,
} from '../../models/IncidentDetection';
import type { PagedResult } from './endpoint';
import { incidentDetectionEndpoint } from './endpoint';

export const incidentDetectionService = {
  getList: (
    filters: IncidentDetectionFilters,
    page = 1,
    pageSize = 20,
  ): Promise<PagedResult<IncidentDetection>> =>
    incidentDetectionEndpoint.getList(filters, page, pageSize),

  getStats: (): Promise<IncidentDetectionStats> =>
    incidentDetectionEndpoint.getStats(),

  getById: (id: string): Promise<IncidentDetection | null> =>
    incidentDetectionEndpoint.getById(id),

  create: (data: Partial<IncidentDetection>): Promise<IncidentDetection> =>
    incidentDetectionEndpoint.create(data),

  update: (id: string, data: Partial<IncidentDetection>): Promise<IncidentDetection> =>
    incidentDetectionEndpoint.update(id, data),

  route: (id: string): Promise<IncidentDetection> =>
    incidentDetectionEndpoint.route(id),

  claim: (id: string): Promise<IncidentDetection> =>
    incidentDetectionEndpoint.claim(id),

  reassign: (
    id: string,
    targetDepartmentId: string,
    targetDepartmentName: string,
  ): Promise<IncidentDetection> =>
    incidentDetectionEndpoint.reassign(id, targetDepartmentId, targetDepartmentName),

  reject: (id: string, reason: string): Promise<IncidentDetection> =>
    incidentDetectionEndpoint.reject(id, reason),

  cancel: (id: string): Promise<IncidentDetection> =>
    incidentDetectionEndpoint.cancel(id),

  convert: (id: string): Promise<{ id: string }> =>
    incidentDetectionEndpoint.convert(id),
};
