import type {
  IncidentPublicReport,
  IncidentPublicReportFilters,
  IncidentPublicReportGuestInit,
  IncidentPublicReportPoster,
  IncidentPublicReportStats,
} from '../../models/IncidentPublicReport';
import type { PagedResult } from './endpoint';
import { incidentPublicReportEndpoint } from './endpoint';

export const incidentPublicReportService = {
  guestInit: (companyCode: string): Promise<IncidentPublicReportGuestInit> =>
    incidentPublicReportEndpoint.guestInit(companyCode),

  submit: (companyCode: string, payload: Record<string, unknown>): Promise<IncidentPublicReport> =>
    incidentPublicReportEndpoint.submit(companyCode, payload),

  mine: (companyCode: string, page = 1, pageSize = 20): Promise<PagedResult<IncidentPublicReport>> =>
    incidentPublicReportEndpoint.mine(companyCode, page, pageSize),

  mineById: (companyCode: string, id: string): Promise<IncidentPublicReport> =>
    incidentPublicReportEndpoint.mineById(companyCode, id),

  getList: (
    filters: IncidentPublicReportFilters,
    page = 1,
    pageSize = 20,
  ): Promise<PagedResult<IncidentPublicReport>> =>
    incidentPublicReportEndpoint.getList(filters, page, pageSize),

  getStats: (): Promise<IncidentPublicReportStats> =>
    incidentPublicReportEndpoint.getStats(),

  getById: (id: string): Promise<IncidentPublicReport | null> =>
    incidentPublicReportEndpoint.getById(id),

  confirm: (id: string): Promise<{ id: string; idCode?: string }> =>
    incidentPublicReportEndpoint.confirm(id),

  reject: (id: string, reason: string): Promise<IncidentPublicReport> =>
    incidentPublicReportEndpoint.reject(id, reason),

  delete: (id: string): Promise<void> =>
    incidentPublicReportEndpoint.delete(id),

  poster: (): Promise<IncidentPublicReportPoster> =>
    incidentPublicReportEndpoint.poster(),
};
