import { createSlice, PayloadAction, createAsyncThunk } from '@reduxjs/toolkit';
import {
  IncidentDetection,
  IncidentDetectionFilters,
  IncidentDetectionStats,
} from '../../models/IncidentDetection';
import { incidentDetectionService } from '../../services/incidentDetections';

interface IncidentDetectionsState {
  items: IncidentDetection[];
  selected: IncidentDetection | null;
  filters: IncidentDetectionFilters;
  loading: boolean;
  saving: boolean;
  error: string | null;
  stats: IncidentDetectionStats;
  pagination: { page: number; pageSize: number; totalCount: number };
}

const initialState: IncidentDetectionsState = {
  items: [],
  selected: null,
  filters: {},
  loading: false,
  saving: false,
  error: null,
  stats: { total: 0, draft: 0, routed: 0, claimed: 0, converted: 0, rejected: 0 },
  pagination: { page: 1, pageSize: 20, totalCount: 0 },
};

export const fetchIncidentDetections = createAsyncThunk(
  'incidentDetections/fetchList',
  async (_, thunkAPI) => {
    const state = thunkAPI.getState() as { incidentDetections: IncidentDetectionsState };
    const { filters, pagination } = state.incidentDetections;
    return incidentDetectionService.getList(filters, pagination.page, pagination.pageSize);
  },
);

export const fetchIncidentDetectionStats = createAsyncThunk(
  'incidentDetections/fetchStats',
  async () => incidentDetectionService.getStats(),
);

export const fetchIncidentDetectionById = createAsyncThunk(
  'incidentDetections/fetchById',
  async (id: string) => incidentDetectionService.getById(id),
);

export const createIncidentDetection = createAsyncThunk(
  'incidentDetections/create',
  async (data: Partial<IncidentDetection>) => incidentDetectionService.create(data),
);

export const updateIncidentDetection = createAsyncThunk(
  'incidentDetections/update',
  async ({ id, data }: { id: string; data: Partial<IncidentDetection> }) =>
    incidentDetectionService.update(id, data),
);

export const routeIncidentDetection = createAsyncThunk(
  'incidentDetections/route',
  async (id: string) => incidentDetectionService.route(id),
);

export const claimIncidentDetection = createAsyncThunk(
  'incidentDetections/claim',
  async (id: string) => incidentDetectionService.claim(id),
);

export const reassignIncidentDetection = createAsyncThunk(
  'incidentDetections/reassign',
  async (args: { id: string; targetDepartmentId: string; targetDepartmentName: string }) =>
    incidentDetectionService.reassign(args.id, args.targetDepartmentId, args.targetDepartmentName),
);

export const rejectIncidentDetection = createAsyncThunk(
  'incidentDetections/reject',
  async ({ id, reason }: { id: string; reason: string }) =>
    incidentDetectionService.reject(id, reason),
);

export const cancelIncidentDetection = createAsyncThunk(
  'incidentDetections/cancel',
  async (id: string) => incidentDetectionService.cancel(id),
);

export const convertIncidentDetection = createAsyncThunk(
  'incidentDetections/convert',
  async (id: string) => incidentDetectionService.convert(id),
);

const applyItem = (s: IncidentDetectionsState, item: IncidentDetection) => {
  const idx = s.items.findIndex((i) => i.id === item.id);
  if (idx >= 0) s.items[idx] = item;
  if (s.selected?.id === item.id) s.selected = item;
};

const incidentDetectionsSlice = createSlice({
  name: 'incidentDetections',
  initialState,
  reducers: {
    setFilters(state, action: PayloadAction<IncidentDetectionFilters>) {
      state.filters = action.payload;
      state.pagination.page = 1;
    },
    setPage(state, action: PayloadAction<number>) {
      state.pagination.page = action.payload;
    },
    setSelectedDetection(state, action: PayloadAction<IncidentDetection | null>) {
      state.selected = action.payload;
    },
    clearError(state) { state.error = null; },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchIncidentDetections.pending, (s) => { s.loading = true; s.error = null; })
      .addCase(fetchIncidentDetections.fulfilled, (s, a) => {
        s.loading = false;
        s.items = a.payload.items;
        s.pagination.totalCount = a.payload.total;
        s.pagination.page = a.payload.page;
      })
      .addCase(fetchIncidentDetections.rejected, (s, a) => {
        if (a.meta.aborted) return;
        s.loading = false;
        s.error = a.error.message ?? 'error';
      });

    builder.addCase(fetchIncidentDetectionStats.fulfilled, (s, a) => { s.stats = a.payload; });

    builder
      .addCase(fetchIncidentDetectionById.pending, (s) => { s.loading = true; s.error = null; })
      .addCase(fetchIncidentDetectionById.fulfilled, (s, a) => {
        s.loading = false;
        s.selected = a.payload;
      })
      .addCase(fetchIncidentDetectionById.rejected, (s, a) => {
        s.loading = false;
        s.error = a.error.message ?? 'error';
      });

    builder
      .addCase(createIncidentDetection.pending, (s) => { s.saving = true; })
      .addCase(createIncidentDetection.fulfilled, (s, a) => {
        s.saving = false;
        s.selected = a.payload;
        s.items.unshift(a.payload);
        s.pagination.totalCount += 1;
      })
      .addCase(createIncidentDetection.rejected, (s, a) => {
        s.saving = false;
        s.error = a.error.message ?? 'error';
      });

    builder
      .addCase(updateIncidentDetection.pending, (s) => { s.saving = true; })
      .addCase(updateIncidentDetection.fulfilled, (s, a) => {
        s.saving = false;
        applyItem(s, a.payload);
      })
      .addCase(updateIncidentDetection.rejected, (s, a) => {
        s.saving = false;
        s.error = a.error.message ?? 'error';
      });

    builder
      .addCase(routeIncidentDetection.pending, (s) => { s.saving = true; })
      .addCase(routeIncidentDetection.fulfilled, (s, a) => { s.saving = false; applyItem(s, a.payload); })
      .addCase(routeIncidentDetection.rejected, (s, a) => { s.saving = false; s.error = a.error.message ?? 'error'; });

    builder
      .addCase(claimIncidentDetection.pending, (s) => { s.saving = true; })
      .addCase(claimIncidentDetection.fulfilled, (s, a) => { s.saving = false; applyItem(s, a.payload); })
      .addCase(claimIncidentDetection.rejected, (s, a) => { s.saving = false; s.error = a.error.message ?? 'error'; });

    builder
      .addCase(reassignIncidentDetection.pending, (s) => { s.saving = true; })
      .addCase(reassignIncidentDetection.fulfilled, (s, a) => { s.saving = false; applyItem(s, a.payload); })
      .addCase(reassignIncidentDetection.rejected, (s, a) => { s.saving = false; s.error = a.error.message ?? 'error'; });

    builder
      .addCase(rejectIncidentDetection.pending, (s) => { s.saving = true; })
      .addCase(rejectIncidentDetection.fulfilled, (s, a) => { s.saving = false; applyItem(s, a.payload); })
      .addCase(rejectIncidentDetection.rejected, (s, a) => { s.saving = false; s.error = a.error.message ?? 'error'; });

    builder
      .addCase(cancelIncidentDetection.pending, (s) => { s.saving = true; })
      .addCase(cancelIncidentDetection.fulfilled, (s, a) => { s.saving = false; applyItem(s, a.payload); })
      .addCase(cancelIncidentDetection.rejected, (s, a) => { s.saving = false; s.error = a.error.message ?? 'error'; });

    builder
      .addCase(convertIncidentDetection.pending, (s) => { s.saving = true; })
      .addCase(convertIncidentDetection.fulfilled, (s) => { s.saving = false; })
      .addCase(convertIncidentDetection.rejected, (s, a) => {
        s.saving = false;
        s.error = a.error.message ?? 'error';
      });
  },
});

export const {
  setFilters,
  setPage,
  setSelectedDetection,
  clearError,
} = incidentDetectionsSlice.actions;

export default incidentDetectionsSlice.reducer;
