import { X_COMPANY_ID_HEADER } from '@linm-soft-org/linm-web-common-components';
import { readActiveCompanyIdForRequest } from './activeCompanyValidate';

declare global {
  interface Window {
    __LINM_TENANT_HEADER_PATCHED__?: boolean;
  }
}

function resolveRequestUrl(input: RequestInfo | URL): string {
  if (typeof input === 'string') return input;
  if (input instanceof URL) return input.href;
  return input.url;
}

function isTenantScopedBffUrl(url: string): boolean {
  try {
    const path = new URL(url, window.location.origin).pathname;
    return path.includes('/web-bff/api/') || path.includes('/api/v1/');
  } catch {
    return url.includes('/web-bff/api/') || url.includes('/api/v1/');
  }
}

function applyCompanyHeader(headers: Headers, companyId: string): void {
  headers.set(X_COMPANY_ID_HEADER, companyId);
}

/**
 * Patch fetch so every BFF call sends validated X-Company-Id (read-only — no event storm).
 * Install after installAuthFetchInterceptor (this wrapper runs outermost).
 */
export function installTenantHeaderInterceptor(): void {
  if (typeof window === 'undefined') return;
  if (window.__LINM_TENANT_HEADER_PATCHED__) return;

  const innerFetch = window.fetch.bind(window);
  window.__LINM_TENANT_HEADER_PATCHED__ = true;

  window.fetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    const url = resolveRequestUrl(input);

    if (isTenantScopedBffUrl(url)) {
      const companyId = readActiveCompanyIdForRequest();
      if (companyId) {
        if (input instanceof Request) {
          const headers = new Headers(input.headers);
          if (init?.headers) {
            new Headers(init.headers).forEach((value, key) => headers.set(key, value));
          }
          applyCompanyHeader(headers, companyId);
          const retryRequest = new Request(input, { headers });
          return innerFetch(retryRequest, init);
        }

        const headers = new Headers(init?.headers);
        applyCompanyHeader(headers, companyId);
        return innerFetch(input, { ...init, headers });
      }
    }

    return innerFetch(input, init);
  };
}
